lv_style_res_tlv_style_get_prop(constlv_style_t*style,lv_style_prop_tprop,lv_style_value_t*value);

voidlv_style_transition_dsc_init(lv_style_transition_dsc_t*tr,constlv_style_prop_tprops[],
lv_anim_path_cb_tpath_cb,uint32_ttime,uint32_tdelay,void*user_data);

lv_style_value_tlv_style_prop_get_default(lv_style_prop_tprop);

staticinlinelv_style_res_tlv_style_get_prop_inlined(constlv_style_t*style,lv_style_prop_tprop,
lv_style_value_t*value)
{
if(style->prop1==LV_STYLE_PROP_ANY){
constlv_style_const_prop_t*const_prop;
uint32_ti;
for(i=0;i<style->prop_cnt;i++){
const_prop=style->v_p.const_props+i;
lv_style_prop_tprop_id=LV_STYLE_PROP_ID_MASK(const_prop->prop);
if(prop_id==prop){
if(const_prop->prop&LV_STYLE_PROP_META_INHERIT)
returnLV_STYLE_RES_INHERIT;
*value=(const_prop->prop&LV_STYLE_PROP_META_INITIAL)?lv_style_prop_get_default(prop_id):const_prop->value;
returnLV_STYLE_RES_FOUND;
}
}
returnLV_STYLE_RES_NOT_FOUND;
}

if(style->prop_cnt==0)returnLV_STYLE_RES_NOT_FOUND;

if(style->prop_cnt>1){
uint8_t*tmp=style->v_p.values_and_props+style->prop_cnt*sizeof(lv_style_value_t);
uint16_t*props=(uint16_t*)tmp;
uint32_ti;
for(i=0;i<style->prop_cnt;i++){
lv_style_prop_tprop_id=LV_STYLE_PROP_ID_MASK(props[i]);
if(prop_id==prop){
if(props[i]&LV_STYLE_PROP_META_INHERIT)
returnLV_STYLE_RES_INHERIT;
if(props[i]&LV_STYLE_PROP_META_INITIAL)
*value=lv_style_prop_get_default(prop_id);
else{
lv_style_value_t*values=(lv_style_value_t*)style->v_p.values_and_props;
*value=values[i];
}
returnLV_STYLE_RES_FOUND;
}
}
}
elseif(LV_STYLE_PROP_ID_MASK(style->prop1)==prop){
if(style->prop1&LV_STYLE_PROP_META_INHERIT)
returnLV_STYLE_RES_INHERIT;
*value=(style->prop1&LV_STYLE_PROP_META_INITIAL)?lv_style_prop_get_default(LV_STYLE_PROP_ID_MASK(
style->prop1)):style->v_p.value1;
returnLV_STYLE_RES_FOUND;
}
returnLV_STYLE_RES_NOT_FOUND;
}

boollv_style_is_empty(constlv_style_t*style);

uint8_t_lv_style_get_prop_group(lv_style_prop_tprop);

uint8_t_lv_style_prop_lookup_flags(lv_style_prop_tprop);

#include"lv_style_gen.h"

staticinlinevoidlv_style_set_size(lv_style_t*style,lv_coord_tvalue)
{
lv_style_set_width(style,value);
lv_style_set_height(style,value);
}

staticinlinevoidlv_style_set_pad_all(lv_style_t*style,lv_coord_tvalue)
{
lv_style_set_pad_left(style,value);
lv_style_set_pad_right(style,value);
lv_style_set_pad_top(style,value);
lv_style_set_pad_bottom(style,value);
}

staticinlinevoidlv_style_set_pad_hor(lv_style_t*style,lv_coord_tvalue)
{
lv_style_set_pad_left(style,value);
lv_style_set_pad_right(style,value);
}

staticinlinevoidlv_style_set_pad_ver(lv_style_t*style,lv_coord_tvalue)
{
lv_style_set_pad_top(style,value);
lv_style_set_pad_bottom(style,value);
}

staticinlinevoidlv_style_set_pad_gap(lv_style_t*style,lv_coord_tvalue)
{
lv_style_set_pad_row(style,value);
lv_style_set_pad_column(style,value);
}

staticinlineboollv_style_prop_has_flag(lv_style_prop_tprop,uint8_tflag)
{
return_lv_style_prop_lookup_flags(prop)&flag;
}

