#ifLV_USE_ASSERT_STYLE
#defineLV_ASSERT_STYLE(style_p)\
do{\
LV_ASSERT_MSG(style_p!=NULL,"ThestyleisNULL");\
LV_ASSERT_MSG(style_p->sentinel==LV_STYLE_SENTINEL_VALUE,"Styleisnotinitializedorcorrupted");\
}while(0)
#else
#defineLV_ASSERT_STYLE(p)do{}while(0)
#endif

